import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import extractText from 'flarum/common/utils/extractText';
import humanTime from 'flarum/common/helpers/humanTime';
import { getFront, loadFront } from '../front';
import { sectionUrl } from '../sections';
const t = (key, params) => app.translator.trans(`ernestdefoe-broadsheet.forum.${key}`, params);

/** Where a story opens: the reader's first unread post, like the discussion list. */
function storyUrl(story) {
  return story.near > 1 ? app.route('discussion.near', {
    id: story.slug,
    near: story.near
  }) : app.route('discussion', {
    id: story.slug
  });
}
function person(user) {
  if (!user) return m("b", null, t('deleted_user'));
  return m(Link, {
    href: app.route('user', {
      username: user.slug
    })
  }, m("b", null, user.name));
}
function kicker(story, extra) {
  if (!story.tag && !extra) return null;
  return m("div", {
    className: "Broadsheet-kicker"
  }, story.tag ? m(Link, {
    href: sectionUrl(story.tag)
  }, story.tag.name) : null, story.tag && extra ? ' · ' : null, extra);
}
function byline(story, replies = true) {
  return m("div", {
    className: "Broadsheet-byline"
  }, t('by', {
    name: person(story.author)
  }), story.createdAt ? [' · ', humanTime(new Date(story.createdAt))] : null, replies ? [' · ', t('replies', {
    count: story.replies
  })] : null);
}

/**
 * The front page: the lead story with the week's most discussed beside it,
 * then three stories in ruled columns.
 *
 * Drawn above core's discussion list, which stays below it as "the rest of
 * the paper": sorting, the sidebar and every extension's list items work as
 * they always do.
 */
export default class Front extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    loadFront().catch(() => {});
  }
  view() {
    const front = getFront();
    if (!front || !front.lead && !front.columns.length) return null;
    return m("section", {
      className: "Broadsheet-front",
      "aria-label": extractText(t('front_page'))
    }, m("div", {
      className: "Broadsheet-top"
    }, front.lead ? this.lead(front.lead) : null, front.mostDiscussed.length ? this.most(front.mostDiscussed) : null), front.columns.length ? m("div", {
      className: "Broadsheet-columns"
    }, front.columns.map(story => this.column(story))) : null);
  }
  lead(story) {
    return m("article", {
      className: 'Broadsheet-lead' + (story.image ? ' Broadsheet-lead--picture' : '')
    }, story.image ? m("figure", {
      className: "Broadsheet-leadPicture"
    }, m(Link, {
      href: storyUrl(story),
      tabindex: "-1",
      "aria-hidden": "true"
    }, m("img", {
      src: story.image,
      alt: "",
      loading: "eager",
      decoding: "async"
    }))) : null, kicker(story, t('lead_label')), m("h2", {
      className: "Broadsheet-leadTitle"
    }, m(Link, {
      href: storyUrl(story)
    }, story.title)), m("div", {
      className: "Broadsheet-leadText"
    }, story.excerpt ? m("p", {
      className: "Broadsheet-standfirst"
    }, story.excerpt) : null, byline(story, false), m("div", {
      className: "Broadsheet-byline"
    }, t('replies', {
      count: story.replies
    }), story.lastReply ? [' · ', t('last_from', {
      name: person(story.lastReply)
    })] : null)));
  }
  most(stories) {
    return m("aside", {
      className: "Broadsheet-most"
    }, m("h2", {
      className: "Broadsheet-rubric"
    }, t('most_discussed')), m("ol", {
      className: "Broadsheet-mostList"
    }, stories.map((story, i) => m("li", {
      key: story.id
    }, m("span", {
      className: "Broadsheet-numeral",
      "aria-hidden": "true"
    }, i + 1), m("div", null, m(Link, {
      className: "Broadsheet-mostTitle",
      href: storyUrl(story)
    }, story.title), m("div", {
      className: "Broadsheet-byline"
    }, story.tag ? [story.tag.name, ' · '] : null, t('replies', {
      count: story.replies
    })))))));
  }
  column(story) {
    return m("article", {
      className: "Broadsheet-column",
      key: story.id
    }, kicker(story), m("h3", {
      className: "Broadsheet-columnTitle"
    }, m(Link, {
      href: storyUrl(story)
    }, story.title)), story.excerpt ? m("p", {
      className: "Broadsheet-columnText"
    }, story.excerpt) : null, byline(story));
  }
}
flarum.reg.add('ernestdefoe-broadsheet', 'forum/components/Front', Front);