import Component from 'flarum/common/Component';

/**
 * A section's own head, on a tag page: its name set like a section front,
 * and its description. Replaces flarum/tags' coloured hero; the tag's colour
 * stays as the rule under the name.
 */
export default class SectionHead extends Component {
  view() {
    const tag = this.attrs.model;
    const color = tag.color();
    return m("div", {
      className: "Broadsheet-sectionHead",
      style: color ? {
        '--bs-section': color
      } : undefined
    }, m("h1", {
      className: "Broadsheet-sectionName"
    }, tag.name()), tag.description() ? m("p", {
      className: "Broadsheet-sectionText"
    }, tag.description()) : null);
  }
}
flarum.reg.add('ernestdefoe-broadsheet', 'forum/components/SectionHead', SectionHead);