import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Dateline from './Dateline';
import Nameplate from './Nameplate';
import SectionNav from './SectionNav';
import Front from './Front';
import SectionHead from './SectionHead';
/**
 * Everything above the discussion list: the nameplate, the section nav, and
 * then the front page itself or the section's head.
 *
 * Stands in IndexPage's hero slot, so core's page (its sidebar, its list,
 * every widget area fof/forum-widgets-core adds around them) is untouched.
 */
export default class BroadsheetHero extends Component {
  view() {
    // 🚨 Not `tag`: Mithril reserves that attribute name and it never arrives.
    const {
      front,
      section: tag
    } = this.attrs;
    const dateline = app.forum.attribute('broadsheetDateline') !== false;
    return m("header", {
      className: "Hero Broadsheet-hero"
    }, m("div", {
      className: "container"
    }, dateline ? m("div", {
      className: "Broadsheet-heroDate"
    }, m(Dateline, null)) : null, m(Nameplate, null), m(SectionNav, {
      front: front,
      current: tag
    }), front ? m(Front, null) : tag ? m(SectionHead, {
      model: tag
    }) : null));
  }
}
flarum.reg.add('ernestdefoe-broadsheet', 'forum/components/BroadsheetHero', BroadsheetHero);