import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';

/**
 * The paper's name, set large and centred, and its tagline.
 *
 * The admin's own wording, else the forum's title and description, so a
 * fresh install reads right before anyone opens the settings page.
 */
export default class Nameplate extends Component {
  view() {
    const name = app.forum.attribute('broadsheetNameplate') || app.forum.attribute('title');
    const tagline = app.forum.attribute('broadsheetTagline') ?? app.forum.attribute('description');
    return m("div", {
      className: "Broadsheet-nameplate"
    }, m(Link, {
      className: "Broadsheet-name",
      href: app.route('index')
    }, name), tagline ? m("p", {
      className: "Broadsheet-tagline"
    }, tagline) : null);
  }
}
flarum.reg.add('ernestdefoe-broadsheet', 'forum/components/Nameplate', Nameplate);